WITH warehouse_perf AS ( SELECT w.w_warehouse_sk, w.w_warehouse_name, w.w_warehouse_sq_ft, SUM(ws.ws_ext_sales_price) AS total_sales, SUM(ws.ws_ext_discount_amt) AS total_discount, SUM(ws.ws_net_profit) AS total_profit, AVG(ws.ws_ext_discount_amt) AS avg_discount, COUNT(DISTINCT ws.ws_item_sk) AS distinct_items_sold FROM web_sales ws JOIN warehouse w ON ws.ws_warehouse_sk = w.w_warehouse_sk GROUP BY w.w_warehouse_sk, w.w_warehouse_name, w.w_warehouse_sq_ft ), brand_sales AS ( SELECT ws.ws_warehouse_sk, i.i_brand, SUM(ws.ws_quantity) AS brand_qty FROM web_sales ws JOIN item i ON ws.ws_item_sk = i.i_item_sk GROUP BY ws.ws_warehouse_sk, i.i_brand ), brand_ranked AS ( SELECT ws_warehouse_sk, i_brand, brand_qty, ROW_NUMBER() OVER (PARTITION BY ws_warehouse_sk ORDER BY brand_qty DESC) AS brand_rank FROM brand_sales ), top_brand_per_warehouse AS ( SELECT ws_warehouse_sk, i_brand AS top_brand FROM brand_ranked WHERE brand_rank = 1 ), warehouse_rank AS ( SELECT wp.*, DENSE_RANK() OVER (ORDER BY (total_profit / NULLIF(w_warehouse_sq_ft,0)) DESC) AS profit_per_sqft_rank, CASE WHEN avg_discount > 0.20 THEN 'High Discount' WHEN avg_discount > 0.10 THEN 'Medium Discount' ELSE 'Low Discount' END AS discount_category FROM warehouse_perf wp ) SELECT wp.w_warehouse_name, wp.w_warehouse_sq_ft, wp.total_sales, wp.total_profit, wp.avg_discount, wp.profit_per_sqft_rank, wp.discount_category, tb.top_brand FROM warehouse_rank wp LEFT JOIN top_brand_per_warehouse tb ON wp.w_warehouse_sk = tb.ws_warehouse_sk ORDER BY wp.profit_per_sqft_rank LIMIT 10
